#include <bits/stdc++.h>
using namespace std;
typedef long long ll;

int main() {
    int n, m;
    scanf("%d %d", &n, &m);
    vector<ll> a(n), out(n, -1);
    for (auto &x : a) scanf("%lld", &x);
    vector<array<ll, 3>> logs(m);
    for (auto &l : logs) scanf("%lld %lld %lld", &l[0], &l[1], &l[2]);
    // Walk the logs backward; floor = largest raise seen after the current point.
    ll floor_ = 0;
    for (int i = m - 1; i >= 0; i--) {
        auto [t, p, x] = logs[i];
        if (t == 2) floor_ = max(floor_, x);
        else if (out[p - 1] < 0) out[p - 1] = max(x, floor_);
    }
    string s = to_string(n) + "\n";
    for (int i = 0; i < n; i++) {
        if (out[i] < 0) out[i] = max(a[i], floor_);
        if (i) s += ' ';
        s += to_string(out[i]);
    }
    puts(s.c_str());
}

import java.io.*;

public class Main {
    static byte[] buf;
    static int pos;

    static void skip() {
        while (pos < buf.length && buf[pos] <= ' ') pos++;
    }

    static String next() {
        skip();
        int s = pos;
        while (pos < buf.length && buf[pos] > ' ') pos++;
        return new String(buf, s, pos - s);
    }

    static long nextLong() {
        skip();
        boolean neg = buf[pos] == '-';
        if (neg) pos++;
        long r = 0;
        while (pos < buf.length && buf[pos] > ' ') r = r * 10 + (buf[pos++] - '0');
        return neg ? -r : r;
    }

    static int nextInt() {
        return (int) nextLong();
    }

    public static void main(String[] args) throws IOException {
        buf = System.in.readAllBytes();
        int n = nextInt(), m = nextInt();
        long[] a = new long[n], out = new long[n];
        for (int i = 0; i < n; i++) a[i] = nextLong();
        java.util.Arrays.fill(out, -1);
        int[] t = new int[m], p = new int[m];
        long[] x = new long[m];
        for (int i = 0; i < m; i++) {
            t[i] = nextInt();
            p[i] = nextInt();
            x[i] = nextLong();
        }
        // Walk the logs backward; floor = largest raise seen after the current point.
        long floor = 0;
        for (int i = m - 1; i >= 0; i--) {
            if (t[i] == 2) floor = Math.max(floor, x[i]);
            else if (out[p[i] - 1] < 0) out[p[i] - 1] = Math.max(x[i], floor);
        }
        StringBuilder sb = new StringBuilder();
        sb.append(n).append('\n');
        for (int i = 0; i < n; i++) {
            if (out[i] < 0) out[i] = Math.max(a[i], floor);
            if (i > 0) sb.append(' ');
            sb.append(out[i]);
        }
        System.out.println(sb);
    }
}

package main

import (
	"bufio"
	"io"
	"os"
	"strconv"
)

var data []byte
var p int

func next() []byte {
	for p < len(data) && data[p] <= ' ' {
		p++
	}
	s := p
	for p < len(data) && data[p] > ' ' {
		p++
	}
	return data[s:p]
}

func nextInt() int64 {
	t := next()
	neg := len(t) > 0 && t[0] == '-'
	if neg {
		t = t[1:]
	}
	var r int64
	for _, c := range t {
		r = r*10 + int64(c-'0')
	}
	if neg {
		return -r
	}
	return r
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n, m := int(nextInt()), int(nextInt())
	a := make([]int64, n)
	out := make([]int64, n)
	for i := range a {
		a[i] = nextInt()
		out[i] = -1
	}
	logs := make([][3]int64, m)
	for i := range logs {
		logs[i] = [3]int64{nextInt(), nextInt(), nextInt()}
	}
	// Walk the logs backward; floor = largest raise seen after the current point.
	var floor int64
	for i := m - 1; i >= 0; i-- {
		t, p, x := logs[i][0], logs[i][1], logs[i][2]
		if t == 2 {
			floor = max(floor, x)
		} else if out[p-1] < 0 {
			out[p-1] = max(x, floor)
		}
	}
	w := bufio.NewWriter(os.Stdout)
	defer w.Flush()
	w.WriteString(strconv.Itoa(n) + "\n")
	for i := 0; i < n; i++ {
		if out[i] < 0 {
			out[i] = max(a[i], floor)
		}
		if i > 0 {
			w.WriteByte(' ')
		}
		w.WriteString(strconv.FormatInt(out[i], 10))
	}
	w.WriteByte('\n')
}
